# Laya RLCD multi-domain fine-tune — REAL typed-decisions trainer (NOT seq2seq).
# GENERATED by the inline domains-generator (same embed as scripts/make_kaggle_kernel.py).
# Trains one checkpoint per dataset attached in /kaggle/input/laya-domain-data/,
# each with the full loop: GRPO-style proper-scoring-rule RLCD + soft CE,
# per-bucket temperature calibration, hard gate (agreement>=0.85, ECE<=0.10).
# Output: /kaggle/working/<domain>-ckpt/ (laya.load() format + eval.json gate table)

import base64, glob, os, subprocess, sys

print("mounted inputs:", os.listdir("/kaggle/input") if os.path.isdir("/kaggle/input") else "NONE", flush=True)
domains = sorted(glob.glob("/kaggle/input/**/*.jsonl", recursive=True))
domains = [d for d in domains if not os.path.basename(d).startswith("combined")]
assert domains, f"no domain jsonl found under {os.listdir('/kaggle/input')}"
print("domains:", [os.path.basename(d) for d in domains], flush=True)

print("installing laya…", flush=True)
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "laya==0.3.5"], check=True)

TRAIN = "/kaggle/working/train_embedded.py"
open(TRAIN, "w").write(base64.b64decode("").decode())
compile(open(TRAIN).read(), "train_embedded.py", "exec")  # sanity before running

results = {}
for ds in domains:
    name = os.path.splitext(os.path.basename(ds))[0]
    out = f"/kaggle/working/{name}-ckpt"
    print(f"\n========== TRAINING {name} -> {out} ==========", flush=True)
    import json as _json
    nrows = sum(1 for _ in open(ds))
    epochs = 2 if nrows > 5000 else 3     # big domains converge fine in 2; saves hours
    print(f"{name}: {nrows} rows -> {epochs} epochs", flush=True)
    r = subprocess.run([
        sys.executable, TRAIN,
        "--dataset", ds,
        "--epochs", str(epochs),
        "--micro-batch", "32",
        "--grad-accum", "1",
        "--device", "cuda",
        "--out", out,
    ])
    results[name] = r.returncode
    gate = os.path.join(out, "eval.json")
    if os.path.isfile(gate):
        print(f"=== GATE TABLE {name} ===", flush=True)
        print(open(gate).read(), flush=True)

print("\n========== SUMMARY ==========", flush=True)
for name, code in results.items():
    print(f"{name}: exit={code} ({'GATE PASS' if code == 0 else 'gate FAIL or error'} - "
          f"register only on PASS after local re-eval)", flush=True)
print("download /kaggle/working/*-ckpt and finetune_register any domain whose eval.json says PASS", flush=True)
